#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }
    int size = 0;
    long heap[100];
    for (int i = 1; i < argc; i++) {
        char *endptr;
        long val = strtol(argv[i], &endptr, 10);
        if (endptr == argv[i]) {
            printf("ERR\n");
            return 0;
        }
        if (size >= 100) {
            printf("FULL\n");
            return 0;
        }
        heap[size++] = val;
        printf("INS %ld\n", val);
    }
    printf("MIN %ld\n", heap[0]);
    return 0;
}
